PG.configure('/subramanya/',[('skanda','Who Is Skanda?','The Six-Faced Son of Śiva'),('shashthi','The Ṣaṣṭhī Story','Skanda Ṣaṣṭhī and Subrahmaṇya Ṣaṣṭhī'),('kukke','Kukke Subrahmaṇya','The Serpent’s Refuge'),('ghati','Ghāṭi Subrahmaṇya','The Twin Images on the Hill')],'navy','Subrahmaṇya Ṣaṣṭhī','Lord','Subrahmaṇya Ṣaṣṭhī')
PG.OUT='outd/sub/'
def cobra(c='#2a6a3a',hoods=1):
    o=f'<path d="M-6 0 q-14 -20 0 -40 q10 -14 0 -30" fill="none" stroke="{c}" stroke-width="9"/>'
    if hoods==1: o+=f'<path d="M-14 -74 q14 -30 28 0 q-14 10 -28 0z" fill="{c}"/>'
    else: o+=''.join(f'<ellipse cx="{(k-3)*9}" cy="{-80+abs(k-3)*3}" rx="7" ry="12" fill="{c}"/>' for k in range(7))
    return o
def nagakallu(): return '<path d="M-26 0 v-60 q26 -24 52 0 v60z" fill="#8a8f9a"/>'+g(0,-8,.6,cobra('#5a5f6a'))
def garuda(): return g(0,0,1.6,bird('#c0582a'))
