def mirror(): return '<rect x="-20" y="-50" width="40" height="50" rx="4" fill="#cfe0f0" stroke="#e0a800" stroke-width="4"/>'
def narasimha(): return '<path d="M-18 0 l4 -40 h28 l4 40z" fill="#e0a800"/><circle cy="-50" r="15" fill="#e0a800"/>'+''.join(f'<path d="M0 -50 l{14*math.cos(k*0.52):.1f} {14*math.sin(k*0.52):.1f}" stroke="#c0582a" stroke-width="5"/>' for k in range(12))+'<circle cy="-50" r="9" fill="#f2c79b"/><circle cx="-3" cy="-52" r="1.6" fill="#111"/><circle cx="3" cy="-52" r="1.6" fill="#111"/>'
def cow_(): return cow()
