def stars6(): return ''.join(f'<circle cx="{-40+k*16}" cy="{-8*(k%2)}" r="4" fill="#ffd60a"/>' for k in range(6))
def fruit(): return '<path d="M0 0 q-14 -6 -10 -24 q8 -10 16 -2 q6 12 -6 26z" fill="#e0a800"/>'
def valli(): return person('#2a9d6f')
def deva(): return person('#c0392b')
# ---------- PART 1: SKANDA ----------
i=0
COV=covart('The six-faced child Skanda on a lotus in a reed lake, six stars above, a peacock and a spear beside',f'<rect width="440" height="196" fill="#e3eaf3"/>'+'<rect y="150" width="440" height="46" fill="#8fb8de"/>'+g(220,60,1.2,stars6())+g(120,186,1,reeds())+g(330,186,1,reeds())+g(220,176,1.4,lotus())+g(220,160,1,skanda())+g(380,186,1.2,peacock()))
pp=[foreword(i,['He is the youngest of the gods and the general of their army. The north knows him as <b>Kārttikeya</b> or <b>Skanda</b>, Tamil Nadu as <b>Murugan</b>, and Karnataka as <b>Subrahmaṇya</b>, very often worshipped in the form of a serpent.','He was born for one job: to kill the demon Tāraka, whom no one but a son of Śiva could defeat. He was born in a bed of reeds, nursed by six star-mothers, given six faces, a spear by his mother and a peacock to ride. This first part meets the god himself: his names, his birth, his signs, the stories of the boy who taught his father and lost a race for a fruit, his two wives, his six abodes, his long history, and why Karnataka sees him in the cobra. Part 2 tells the '+L('/subramanya/shashthi/','Ṣaṣṭhī')+' war; Parts 3 and 4 visit Kukke and Ghāṭi.'],[('z','Why so many names for one god?'),('b','Because almost every region of India loved him in its own way, Zappy. Each name keeps one story.')]),
 glance([('Who','Son of Śiva and Pārvatī; younger brother of Gaṇeśa in the south (the elder in some northern tellings)'),('Role','Devasenāpati, general of the gods’ army'),('Born','In the reed lake Śaravaṇa; nursed by the six Kṛttikās (the Pleiades)'),('Look','Ever young; one or six faces; holding the vel (spear)'),('Mount, flag','The peacock; the rooster on his banner'),('Consorts','Devasenā (Devayānai) and Vaḷḷi in the south; a lifelong bachelor in many northern traditions'),('Key day','Ṣaṣṭhī, the sixth lunar day (Part 2)'),('Karnataka','Subrahmaṇya, often as a cobra; Kukke and Ghāṭi')],svg(560,140,'Skanda with spear, peacock and rooster',f'<rect width="560" height="140" fill="#e3eaf3"/>'+g(200,130,1.1,peacock())+g(200,104,1,skanda())+g(330,130,1.2,rooster())+g(440,130,1.2,anthill()))),
 cards('names','HIS NAMES','One god, many stories',fig_row('Skanda, six stars, reeds and a cave',[(skanda(),1),(stars6(),1),(reeds(),1),(cave(),.6)],['Skanda','Kārttikeya','Śaravaṇabhava','Guha'],gy=150),[('⚡','Skanda, Kumāra','<b>Skanda</b>, “the one who leaps” or “attacks”: the spurt of Śiva’s energy. <b>Kumāra</b>, “the youth”: he never grows old.'),('✨','Kārttikeya, Ṣaṇmukha','“Son of the Kṛttikās”, the six star-mothers; <b>Ṣaṇmukha</b>, “six-faced” (Āṟumukham in Tamil); <b>Śaravaṇabhava</b>, “born in the reeds”.'),('🕳️','Guha, Subrahmaṇya','<b>Guha</b>, “the hidden one”, who lives in the cave of the heart. <b>Subrahmaṇya</b> is often read as “dear to the brāhmaṇas” or “of Brahman”; its meaning is debated.'),('🌺','Murugan, Subbarāya','Tamil <b>Murugan</b>, “the beautiful”, god of the hills; <b>Vēlan</b>, the spear-bearer. In Karnataka homes, <b>Subbarāya</b>, <b>Subbappa</b>.')],[('z','Which name should I use?'),('b','Any of them, Zappy. In Karnataka, “Subbarāya” or “Subrahmaṇya Svāmi” is what grandmother says.')],'Many names, <b>one boy-god</b>.'),
 story('why','A DEMON ONLY A CHILD COULD KILL','Why he was born',strip('Three panels: the demon Tāraka receiving a boon from Brahmā; Śiva in meditation unaware; Kāma burned by the third eye and Pārvatī in penance',[panel([(demon('#5a3a6a'),1),(god('#c0392b'),.8)],'#fde4e4',150),panel([(shiva(),1)],'#e3eaf3',150),panel([(flames(),.8),(devi(sari='#fff',items=('rosary','kamandalu')),.8)],'#fff3cf',150)],['Tāraka’s boon','Śiva withdrawn','Kāma and Pārvatī']),'Śiva Purāṇa and Kālidāsa’s Kumārasambhava, “the birth of the prince”.',['The demon <b>Tāraka</b> won a boon from Brahmā: he could be killed only by a son of Śiva. Śiva, mourning Satī, was lost in meditation and had no wife. Tāraka felt safe.','He drove the gods from heaven. Indra and the gods went to Brahmā, who told them: only Śiva’s son can save you.','The gods sent <b>Kāma</b>, god of love, to wake Śiva. Śiva opened his third eye and burned Kāma to ash (read our '+L('/festivals/holi/','Holi')+' article).','<b>Pārvatī</b> won Śiva by her own fierce penance, and they married. This is the story of Kālidāsa’s <i>Kumārasambhava</i>.','From Śiva came a blaze of energy so fierce that no one could hold it. Where it went next is the story of the birth.'],[('z','The whole universe waited for one child?'),('b','A very special one, Zappy. The gods needed a hero only Śiva and Pārvatī could give.')],'The world <b>waits for a child</b>.'),
 story('birth','BORN IN THE REEDS','Fire, river, lake and six stars',strip('Three panels: Agni carrying the fiery seed; Gaṅgā carrying it to a reed lake; six star-mothers nursing six babies who become one',[panel([(agni(),1)],'#fde4e4',150),panel([(river(144,120),1),(reeds(),.8)],'#dfe9f6',None),panel([(stars6(),1),(baby(),.6),(devi(sari='#2a9d6f',items=('lotus',)),.7)],'#fff3cf',150)],['Agni carries it','Gaṅgā cools it','six become one']),'Rāmāyaṇa and Mahābhārata, the Purāṇas, and the Tamil Kanda Purāṇam; tellings differ.',['The fire-god <b>Agni</b> took Śiva’s blazing seed, but even he could not bear its heat.','He gave it to the river <b>Gaṅgā</b>, who carried it to a lake of reeds, <b>Śaravaṇa</b>, in the Himālaya.','There it became six shining boys, each on a lotus. In the Tamil Kanda Purāṇam, six sparks from Śiva’s six faces go straight to the lake.','The six <b>Kṛttikās</b>, the stars of the Pleiades, came down and nursed them: so he is Kārttikeya.','<b>Pārvatī</b> came and embraced all six at once, and they became one child with six faces and twelve arms. (Our Navarātri '+L('/festivals/navaratri/skandamata/','Skandamātā')+' night tells the mother’s side.)'],[('z','Why six?'),('b','Six mothers, six faces, six days of war, the sixth lunar day, Zappy. With Skanda, everything comes in sixes.')],'Six mothers, <b>one child</b>.'),
 reading('signs','THE VEL, THE PEACOCK, THE ROOSTER','His three signs',svg(560,170,'The spear, a peacock and a rooster in a row, with a snake under the peacock’s feet',f'<rect width="560" height="170" fill="#e3eaf3"/>'+g(140,160,1.6,vel())+g(290,160,1.6,peacock())+g(290,164,.6,cobra())+g(430,160,1.6,rooster())),['<b>The vel.</b> A spear with a leaf-shaped blade, given by his mother Pārvatī. Tamil devotees read its long shaft and broad tip as knowledge: deep, wide and sharp. The cry “<i>Vetrivel Muruganukku arōharā</i>”, victory to Murugan of the conquering spear, rings at every festival.','<b>The peacock.</b> His mount. In the Tamil telling it is half of the defeated demon Śūrapadma; many read it as pride tamed (read '+L('/subramanya/shashthi/','Part 2')+').','<b>The rooster.</b> On his banner, the other half of Śūrapadma, crowing at dawn.','<b>The snake.</b> Many images show a snake under the peacock’s feet: the peacock eats snakes. Yet in Karnataka the god himself is worshipped as a serpent. That puzzle is the heart of Parts 3 and 4.'],[('z','His peacock eats snakes, and he is a snake?'),('b','Karnataka holds both, Zappy. Parts 3 and 4 explain how.')],'Spear, peacock, <b>rooster</b>.'),
 story('om','THE TEACHER OF HIS FATHER','Svāminātha',strip('Three panels: the boy questioning Brahmā about Om; Brahmā locked up; Śiva listening as a disciple while the boy whispers in his ear',[panel([(child(),1),(god('#c0392b'),.9)],'#fff3cf',150),panel([(god('#c0392b'),.9),('<path d="M-30 -60 v60 M-10 -60 v60 M10 -60 v60 M30 -60 v60" stroke="#666" stroke-width="3"/>',1)],'#e9e3f5',150),panel([(shiva(),.9),(child(),.8)],'#e3eaf3',150)],['what is Om?','Brahmā confined','the father listens']),'A Tamil temple tradition of Svāmimalai; versions differ.',['The boy Skanda asked Brahmā, the creator, what <b>Om</b> (the Praṇava) means. Brahmā could not explain it.','Skanda locked Brahmā up and took over creation himself.','Śiva came to free Brahmā and asked his son: “Then you tell me what Om means.”','Śiva sat as a disciple and the boy whispered the meaning in his ear. So he is <b>Svāminātha</b>, “teacher of the Lord”, at <b>Svāmimalai</b> near Kumbakōṇam.','The point the tradition draws: wisdom does not depend on age.'],[('z','A child taught Śiva?'),('b','And Śiva was happy to learn, Zappy. That’s the other half of the lesson.')],'Wisdom <b>does not wait for age</b>.'),
 story('fruit','THE FRUIT OF WISDOM','Round the world, or round your parents?',strip('Three panels: Nārada offering a golden fruit to Śiva and Pārvatī; Skanda flying off on his peacock while Gaṇeśa walks round his parents; Skanda alone on Paḻani hill with a staff',[panel([(sage('#ff8c1a'),.8),(fruit(),1.2),(shiva(),.7)],'#fff3cf',150),panel([(peacock(),.8),(ganesha(seat=False),.6)],'#e3eaf3',150),panel([(mountain('#8a7a5a',False),.8),(child(),.6)],'#fde9c8',150)],['one fruit','the race','Paḻani']),'A widely told South Indian story.',['The sage <b>Nārada</b> brought a single golden fruit (a mango, in most tellings) to Śiva and Pārvatī. Who should have it?','“Whoever goes round the world first,” said Śiva. Skanda leapt on his peacock and flew off.','<b>Gaṇeśa</b> simply walked round his parents: “You are my world.” He won the fruit.','Skanda came back, felt cheated, gave up his finery and went to live alone on the hill of <b>Paḻani</b>, as a young renunciant with a staff.','Pārvatī followed: “<i>Paḻam nī</i>”, “you are the fruit.” Folk etymology hears “Paḻani” in it.'],[('z','So who was right?'),('b','Both, Zappy. Gaṇeśa shows love for parents; Skanda shows that the seeker must leave home. The fruit was the lesson.')],'You <b>are</b> the fruit.'),
 verse('v-bhuj4','Subrahmaṇya Bhujaṅgam, verse 4','The god by the sea who carries us across',['yadā sannidhānaṃ gatā mānavā me','bhavāmbhodhipāraṃ gatās te tadaiva','iti vyañjayan sindhutīre ya āste','tam īḍe pavitraṃ parāśaktiputram'],svg(200,150,'Skanda standing by the sea with waves behind him',f'<rect width="200" height="150" fill="#e3eaf3"/>'+'<path d="M0 110 q50 -10 100 0 t100 0 v40 h-200z" fill="#8fb8de"/>'+g(100,140,1.2,skanda())),'“When people come into my presence, at that very moment they have crossed the ocean of worldly life”: as if to show this, he stands on the shore of the sea. I praise him, the pure son of the supreme Śakti.',[('sannidhānam','presence'),('bhava-ambhodhi','the ocean of worldly life'),('pāram gatāḥ','have crossed'),('sindhu-tīre','on the sea shore'),('pavitram','pure'),('parāśakti-putram','son of the supreme Śakti')],'<b>Tiruccendūr.</b> Śaṅkara composed the Bhujaṅgam at Murugan’s seashore temple, and this verse makes the shore itself a sermon: the god stands at the edge of the ocean to show he carries devotees across the ocean of births.',k='The god <b>on the shore</b>.',note='Text as on shlokam.org (Subramanya Bhujangam), verse 4.'),
 reading('consorts','DEVASENĀ AND VAḶḶI','Two wives, two worlds',svg(560,170,'Skanda standing between two consorts, one royal and one a hill-girl with a sling',f'<rect width="560" height="170" fill="#e3eaf3"/>'+g(280,160,1.3,skanda())+g(180,160,1.2,deva())+g(380,160,1.2,valli())+g(420,120,.8,'<path d="M0 0 q10 -20 20 0" fill="none" stroke="#6a4a2a" stroke-width="3"/>')),['<b>Devasenā.</b> Daughter of Indra (in the Skanda Purāṇa; of Dakṣa in the Mahābhārata). Her name means “the army of the gods”: the general marries his army. In Tamil, Devayānai. Karnataka’s tradition places the wedding near Kukke (Part 3).','<b>Vaḷḷi.</b> Daughter of a hill-tribe chief, who guarded millet fields with a sling. Murugan wooed her disguised as a hunter and an old man, with Gaṇeśa’s help as a wild elephant.','<b>The pair.</b> Many read them as two powers: Devasenā, action (<i>kriyā</i>); Vaḷḷi, desire or love (<i>icchā</i>); the vel, knowledge (<i>jñāna</i>). (Interpretation.)','<b>The bachelor.</b> In many northern traditions Kārttikeya stays a lifelong bachelor, and women traditionally kept out of some of his shrines.'],[('z','The general married an army?'),('b','Devasenā means exactly that, Zappy. The Purāṇas love a good pun.')],'Royal and tribal, <b>both his own</b>.'),
 cards('abodes','THE SIX ABODES','Āṟupaṭai Vīṭu of Tamil Nadu',fig_row('Six hill temples in a row',[(palace(),.45)]*6,['Paraṅkuṉṟam','Cendūr','Paḻani','Svāmimalai','Taṇi','Cōlai'],gy=150),[('💍','Tirupparaṅkuṉṟam and Tiruttaṇi','Near Madurai, his wedding with Devasenā; near Chennai, peace after the war and his marriage to Vaḷḷi.'),('🌊','Tiruccendūr','On the seashore: victory over Śūrapadma and the great Sūrasaṃhāram of Skanda Ṣaṣṭhī.'),('⛰️','Paḻani and Svāmimalai','The hill of the fruit, the renunciant boy with a staff; near Kumbakōṇam, the teacher of Om.'),('🌳','Paḻamudircōlai','Near Madurai, in the forest: Vaḷḷi and Devasenā together. The “six camps” come from Nakkīrar’s Tirumurukāṟṟuppaṭai, a Tamil pilgrims’ guide-poem well over a thousand years old.')],[('z','Six again?'),('b','Of course, Zappy. Many read the six as six chapters of his life: wisdom, war, renunciation, teaching, peace, union.')],'Six homes, <b>six chapters</b>.'),
 reading('history','HOW OLD IS HE?','From the Vedas to Kuṣāṇa coins',svg(560,150,'A timeline from Vedic texts to coins and poems',f'<rect width="560" height="150" fill="#fffaf0"/>'+'<path d="M30 80 h500" stroke-width="3"/>'+''.join(g(x,74,1,lamp())+lab(x,100,t)+lab(x,116,s) for x,t,s in [(70,'Veda','Kumāra'),(190,'epics','birth'),(310,'1st–2nd c.','coins'),(430,'5th–6th c.','Purāṇa, poem')])),['<b>Vedic hints.</b> A bright boy called Kumāra appears in the Ṛgveda; the Taittirīya Āraṇyaka names Ṣaṇmukha; the Chāndogya Upaniṣad calls the sage Sanatkumāra by the name Skanda.','<b>Grammarians and epics.</b> Pāṇini, Patañjali and Kauṭilya’s Arthaśāstra know Skanda; the Rāmāyaṇa and Mahābhārata tell his birth, with Agni and Gaṅgā.','<b>Coins.</b> Kuṣāṇa and Yaudheya coins of the first and second centuries CE show him with spear and peacock; six-faced images are firmly established after about the sixth century.','<b>The South and the Purāṇa.</b> The Tamil Sangam poems make Murugan the god of the hills; the <b>Skanda Purāṇa</b>, the largest Purāṇa, carries his name; Kālidāsa’s Kumārasambhava (about the fifth century) tells his birth.'],[('z','He’s on old coins?'),('b','Over 1,800 years old, Zappy, spear and peacock and all.')],'Two thousand years <b>of the boy-god</b>.'),
 reading('karnataka','SUBRAHMAṆYA IN KARNATAKA','The god who is a serpent',svg(560,170,'A seven-hooded cobra stone under a tree beside an anthill with lamps',f'<rect width="560" height="170" fill="#cfe0d8"/>'+'<rect y="140" width="560" height="30" fill="#a8c890"/>'+g(160,150,1.1,tree('#2f6a3a'))+g(170,150,1.2,nagakallu())+g(320,150,1.4,cobra(hoods=7))+g(450,150,1.1,anthill())),['<b>Serpent form.</b> Along the west coast and across Karnataka, Subrahmaṇya is worshipped as a <b>nāga</b>, a cobra, often seven-hooded.','<b>Anthills and stones.</b> The anthill (<b>huttu</b>), the cobra’s home, is worshipped as his shrine; stone serpent images (<b>nāgara kallu</b>) stand under trees, installed after vows, often for children.','<b>Why?</b> An old serpent worship of the coast and the Malnāḍ joined the cult of Skanda. Scholars and traditions differ on how; many point to the Ṣaṣṭhī and Pañcamī days that both share.','<b>Great shrines and days.</b> '+L('/subramanya/kukke/','Kukke Subrahmaṇya')+' (Part 3) and '+L('/subramanya/ghati/','Ghāṭi Subrahmaṇya')+' (Part 4); '+L('/festivals/naga-panchami/','Nāgara Pañcamī')+' and Subrahmaṇya Ṣaṣṭhī.'],[('z','So in Karnataka, the snake is the god?'),('b','The god in the snake, Zappy. You’ll see it clearly at Kukke.')],'The war-god <b>as a cobra</b>.'),
 end(i,['<b>Who.</b> Skanda, Kārttikeya, Murugan, Subrahmaṇya: Śiva’s son, general of the gods.','<b>Birth.</b> Śiva’s spark, Agni and Gaṅgā, the reeds of Śaravaṇa; six Kṛttikās; one child, six faces.','<b>Signs.</b> The vel from his mother, the peacock and the rooster.','<b>Stories.</b> Teacher of Om; the fruit and Paḻani; Devasenā and Vaḷḷi; six abodes.','<b>Karnataka.</b> Worshipped as a serpent, at the anthill, at Kukke and Ghāṭi.'],'Part 2 tells the war he was born for: '+L('/subramanya/shashthi/','the Ṣaṣṭhī story')+'.','Who is Skanda?'),
 sources([('Names, birth, history:','Wikipedia, “Kartikeya” (names; Rāmāyaṇa and Mahābhārata births; Skanda Purāṇa’s six sparks fused by Pārvatī; Kumārasambhava; Kanda Purāṇam; vel from Pārvatī; peacock and rooster from Śūrapadma; Kuṣāṇa and Yaudheya coins; Vedic references; Tirumurukāṟṟuppaṭai), as summarised in our earlier guide.'),('Verse:','Subrahmaṇya Bhujaṅgam, verse 4, as on shlokam.org.')],'the Svāmimalai and Paḻani stories (temple traditions; versions differ); the meaning of “Subrahmaṇya” (debated); how serpent worship joined Skanda’s cult in Karnataka (scholars differ); the readings of the six faces and two consorts (interpretations).','Interpretations are marked as such.')]
build(i,'PART 1 OF 4 · SIX FACES · THE VEL AND THE PEACOCK',COV,'Born in the reeds','His <b>names</b>, his <b>birth</b> in the reeds, his <b>signs</b>, the boy who taught Śiva and lost a race for a fruit, his wives and six abodes, his long <b>history</b>, and why Karnataka sees him as a <b>serpent</b>.','Who is Skanda? Kārttikeya, Murugan and Subrahmaṇya explained: his names, why he was born, his birth in the reeds and the six Kṛttikās, the vel, peacock and rooster, Svāminātha and the fruit of Paḻani, Devasenā and Vaḷḷi, the six abodes, his history from the Vedas to coins, and Subrahmaṇya as a serpent in Karnataka. Part 1 of 4.',pp)
print('skanda',len(pp)+2)
# ---------- PART 3: KUKKE ----------
i=2
COV=covart('A forest temple beside a river below a peak, a seven-hooded serpent and an eagle kept at a distance, a great chariot',f'<rect width="440" height="196" fill="#e3f5e9"/>'+g(330,150,1.6,mountain('#5a7a4a',False))+'<path d="M0 170 q220 -16 440 0 v26 h-440z" fill="#8fb8de"/>'+g(200,160,1.1,palace())+g(90,170,1.2,cobra(hoods=7))+g(390,60,.8,bird('#c0582a'))+g(300,186,1.1,chariot()))
pp=[foreword(i,['Deep in the forests of the Western Ghāṭs, where the Kumāradhārā river comes down from <b>Kumāra Parvata</b>, Śiva’s son is worshipped not as a warrior with a spear but as the lord of serpents. Here, the story goes, the great serpent <b>Vāsuki</b> hid in a cave from <b>Garuḍa</b>, and Subrahmaṇya promised to stay with him forever.','So at Kukke the god and the serpent are worshipped together, and families from all over India come for the rites of the nāgas. This part tells the stories, walks through the shrine and its neighbours, explains the rites honestly, gives a verse of the Bhujaṅgam, and describes the festival that makes Kukke the heart of Subrahmaṇya Ṣaṣṭhī.'],[('z','A god worshipped as a snake?'),('b','As the snake’s protector, and in the snake, Zappy. At Kukke the two cannot be separated.')]),
 glance([('Where','Subrahmaṇya village, Kaḍaba taluk, Dakṣiṇa Kannaḍa, on the Kumāradhārā river'),('God','Subrahmaṇya as lord of the serpents, with Vāsuki and Śeṣa'),('Setting','Forest of the Western Ghāṭs, below Kumāra Parvata'),('Legends','Vāsuki’s refuge from Garuḍa; Skanda’s wedding with Devasenā'),('Known for','Serpent rites: sarpa saṃskāra, āśleṣā bali, nāga pratiṣṭhā'),('Worship','Daily rites following Madhvācārya’s Tantrasāra Saṅgraha'),('Festival','Campā Ṣaṣṭhī (Mārgaśīrṣa Śuddha Ṣaṣṭhī) with the Brahmaratha'),('Tradition','One of the seven holy places of the west coast said to be set up by Paraśurāma')],svg(560,140,'A forest temple by a river with a serpent',f'<rect width="560" height="140" fill="#e3f5e9"/>'+hills(560,130)+'<path d="M0 125 q280 -10 560 0 v15 h-560z" fill="#8fb8de"/>'+g(280,120,.9,palace())+g(440,130,1,cobra(hoods=7)))),
 cards('names','ITS NAMES','Kukke, Subrahmaṇya, Subbappa',fig_row('A liṅga, a serpent, a plate of food and a temple',[(linga(),1.2),(cobra(),1),(plate(),1.5),(palace(),.6)],['Kukke liṅga','Ahipeśvara','Annadāta','the temple'],gy=150),[('🛕','Kukke Subrahmaṇya','The temple’s common name; “Kukke” is tied to the old Kukke liṅga worshipped here. The village around it is simply called Subrahmaṇya.'),('🐍','Ahipeśvara','“Lord of serpents”: an old name of the Kukke liṅga.'),('🍚','Annadāta Subbappa','“Subbappa the giver of food”: the temple is known for feeding every pilgrim.'),('🙏','Subbappa, Subbarāya','Affectionate Kannaḍa and Tuḷu names for the god.')],[('z','Why is he called the giver of food?'),('b','Because nobody leaves Kukke hungry, Zappy. The temple feeds thousands every day.')],'Many names, <b>one refuge</b>.'),
 story('vasuki','VĀSUKI AND GARUḌA','The serpent who hid in a cave',strip('Three panels: Garuḍa hunting serpents; Vāsuki praying in a cave; Subrahmaṇya blessing Vāsuki',[panel([(garuda(),.8),(cobra(),.6)],'#dfe9f6',150),panel([(cave(),.9),(cobra(),.5)],'#6a5a4a',150),panel([(skanda(),.9),(cobra(hoods=7),.8)],'#fff3cf',150)],['the hunter','the cave','the promise']),'Temple tradition, with the Skanda Purāṇa (Sahyādri Khaṇḍa) cited by the temple; tellings differ.',['<b>Garuḍa</b>, the eagle who carries Viṣṇu, was the old enemy of the serpents and hunted them to eat. (Why, is told in our '+L('/festivals/naga-panchami/','Nāga Pañcamī')+' article.)','<b>Vāsuki</b>, king of serpents and a great devotee of Śiva, hid in a cave called <b>Biladvāra</b> near the Kumāradhārā, deep in prayer.','In one telling Garuḍa found him and attacked, until the sage <b>Kaśyapa</b>, father of both, asked him to spare Śiva’s devotee.','Vāsuki prayed to Śiva for safety. Śiva sent him to his son: “Subrahmaṇya will protect you.”','Subrahmaṇya came, blessed Vāsuki and promised to stay here with him forever. So worship of Vāsuki here is worship of Subrahmaṇya.'],[('z','Isn’t the peacock also a snake-eater?'),('b','Yes, and still it is the snake who gets refuge, Zappy. The god protects even his mount’s prey.')],'Refuge for <b>the hunted</b>.'),
 story('wedding','THE WEDDING AND THE RIVER','Kumāra Parvata and the Kumāradhārā',strip('Three panels: Skanda and Gaṇeśa arriving at the peak; Indra giving Devasenā; waters of all rivers flowing down as one',[panel([(skanda(),.9),(ganesha(seat=False),.6),(mountain('#6a8a5a',False),.6)],'#e3f5e9',150),panel([(god('#e0a800'),.8),(deva(),.8),(skanda(),.8)],'#fff3cf',150),panel([(river(144,120),1),(mountain('#6a8a5a',False),.5)],'#dfe9f6',None)],['to the peak','the wedding','the river']),'Kukke temple tradition.',['In this tradition, after killing Tāraka and Śūrapadma, Skanda came with Gaṇeśa to the peak now called <b>Kumāra Parvata</b>.','Indra gave him his daughter <b>Devasenā</b> on Mārgaśīrṣa Śuddha Ṣaṣṭhī, with the gods present.','Waters of all the sacred rivers, brought for the wedding, flowed down as the <b>Kumāradhārā</b>, “the stream of Kumāra”.','Another telling says he washed his vel in this river after the war.','So pilgrims bathe in the Kumāradhārā before entering the temple, and the wedding day is the temple’s great festival. The full war is in '+L('/subramanya/shashthi/','Part 2')+'.'],[('z','A river made of wedding water?'),('b','That’s the story, Zappy. Bathe in it and you’ve been to the wedding.')],'A river <b>from a wedding</b>.'),
 reading('sanctum','THE SANCTUM','God above, serpents below',svg(560,170,'A sanctum with three tiers: the god seated on top, a serpent in the middle, another serpent below, and a pillar in front',f'<rect width="560" height="170" fill="#fffaf0"/>'+'<rect x="200" y="20" width="160" height="140" fill="#e3eaf3" stroke="#111" stroke-width="2"/>'+g(280,70,.7,skanda())+g(280,115,.7,cobra(hoods=7))+g(280,158,.6,cobra('#4a6a8a'))+'<rect x="420" y="40" width="20" height="120" fill="#d8d8e0" stroke="#111" stroke-width="2"/>'+lab(430,30,'Garuḍa pillar')),['<b>Three tiers.</b> As commonly described: at the top <b>Subrahmaṇya</b>, seated, lord of the shrine; in the middle <b>Vāsuki</b>, king of serpents, whom he protects; at the base <b>Śeṣa</b> (Ādiśeṣa), the serpent Viṣṇu rests on.','<b>The Garuḍa pillar.</b> A silver-covered pillar stands between the sanctum and the entrance. Tradition says it shields devotees from the fiery breath of Vāsuki: Garuḍa cannot touch Vāsuki, and Vāsuki’s breath cannot touch you.','<b>Darśan.</b> Devotees enter from the back (east) gate in many accounts, after the river bath, and walk round to the front. Customs and queue arrangements are set by the temple.','<b>The worship.</b> Daily rites follow Madhvācārya’s <i>Tantrasāra Saṅgraha</i>, the ritual manual of the Mādhva tradition.'],[('z','Garuḍa guards the people from the serpent?'),('b','Neatly balanced, Zappy. Even the eagle has a job here.')],'God above, <b>serpents below</b>.'),
 reading('adi','ĀDI SUBRAHMAṆYA AND BILADVĀRA','The anthill and the cave',svg(560,170,'A small shrine with an anthill inside, a cave entrance and a stream',f'<rect width="560" height="170" fill="#e3f5e9"/>'+'<rect y="140" width="560" height="30" fill="#a8c890"/>'+g(150,150,1.2,anthill())+'<path d="M110 150 v-90 h80 v90" fill="none" stroke="#6a4a2a" stroke-width="4"/>'+g(340,150,1,cave())+'<path d="M420 150 q60 -10 140 0" stroke="#8fb8de" stroke-width="8" fill="none"/>'),['<b>Ādi Subrahmaṇya.</b> A short walk from the main temple is a separate shrine where an <b>anthill</b> (<i>valmīka</i>) in the sanctum is worshipped every day. “Ādi” means first: it is held to be the original seat of the serpent god.','<b>Biladvāra.</b> “The door of the hole”: the cave where Vāsuki is said to have hidden and prayed.','<b>Kāśikaṭṭe Gaṇapati.</b> An old Gaṇeśa shrine nearby, said in tradition to have been set up by Nārada.','<b>Darpaṇa tīrtha.</b> A stream behind the temple, flowing into the Kumāradhārā.'],[('z','Why an anthill?'),('b','It’s a cobra’s home, Zappy. At Ādi Subrahmaṇya the home itself is the shrine.')],'The <b>first seat</b>.'),
 reading('linga','THE KUKKE LIṄGA AND ŚAṄKARA','Father and son in one house',svg(560,160,'A liṅga with a serpent hood above it and a monk with a staff',f'<rect width="560" height="160" fill="#e3eaf3"/>'+g(220,150,1.3,linga())+g(220,105,.7,cobra(hoods=7))+g(380,150,1.1,sage('#ff8c1a'))),['<b>The Kukke liṅga.</b> Before the present image, tradition says, worship centred on the <b>Kukke liṅga</b>, called Ahipeśvara, “lord of serpents”: the son’s name was first written on the father’s stone.','<b>Śaṅkara.</b> Ādi Śaṅkara’s traditional biographies record his visit here, and the Subrahmaṇya Bhujaṅgam is often linked with this shrine (next page).','<b>Two lineages.</b> A Śṛṅgeri maṭha and the Candramaulīśvara shrine stand in the precincts; the Subrahmaṇya Maṭha of the Mādhva tradition is beside the temple. Both traditions have long roots here.','<b>One family.</b> Śiva, Subrahmaṇya, Vāsuki, Gaṇeśa: Kukke is a whole Śaiva household gathered in one forest.'],[('z','A Śiva liṅga in Subrahmaṇya’s temple?'),('b','Father and son share the house, Zappy.')],'Father and son <b>share the house</b>.'),
 verse('v-bhuj5','Subrahmaṇya Bhujaṅgam, verse 5','Troubles vanish like waves',['yathābdhes taraṅgā layaṃ yānti tuṅgās','tathaivāpadaḥ sannidhau sevatāṃ me','itīvormipaṅktīr nṛṇāṃ darśayantaṃ','sadā bhāvaye hṛtsaroje guhaṃ tam'],svg(200,150,'Waves rising and falling before Skanda',f'<rect width="200" height="150" fill="#e3eaf3"/>'+''.join(f'<path d="M0 {90+k*14} q25 -12 50 0 t50 0 t50 0 t50 0" fill="none" stroke="#5a8ab8" stroke-width="3"/>' for k in range(3))+g(100,90,1,skanda())),'“Just as high waves of the ocean sink to rest, so do the troubles of those who serve me in my presence”: as if to show this to people through the rows of waves, he stands; I always meditate on that Guha in the lotus of my heart.',[('abdheḥ taraṅgāḥ','waves of the ocean'),('layaṃ yānti','dissolve'),('āpadaḥ','troubles'),('sannidhau','in the presence'),('ūrmi-paṅktīḥ','rows of waves'),('hṛt-saroje','in the heart-lotus')],'<b>The serpent metre.</b> The Bhujaṅgam is written in the <i>bhujaṅga-prayāta</i> metre, “the serpent’s glide”: a fitting hymn for Karnataka’s serpent shrine, where devotees come precisely to have their troubles subside. Families often recite it during the rites at Kukke.',k='Troubles <b>sink like waves</b>.',note='Text as on shlokam.org (Subramanya Bhujangam), verse 5.'),
 reading('rites','THE NĀGA RITES','Why families come to Kukke',svg(560,160,'A family seated before a priest with a small serpent image and offerings',f'<rect width="560" height="160" fill="#fffaf0"/>'+'<rect y="135" width="560" height="25" fill="#e9d6c0"/>'+g(160,140,1.1,sage('#ff8c1a'))+g(260,140,1.2,nagakallu())+g(360,140,1,person('#c0392b',seat=True))+g(420,140,1,person('#2a5aa8',seat=True))+g(480,140,1.2,lamp())),['<b>Sarpa saṃskāra.</b> A two-day rite, like last rites for a serpent, done by those who believe they harmed a snake, in this life or another.','<b>Āśleṣā bali.</b> A rite on the day of the <b>Āśleṣā</b> star, sacred to the serpents.','<b>Nāga pratiṣṭhā.</b> Installing a stone serpent image, often after a vow. Families seek children, health, marriage, and relief from <b>sarpa doṣa</b>, the trouble believed to follow harm to serpents.','<b>A frank note.</b> These rites rest on belief; their rules, timings and fees are set by the temple and should be checked with it directly. What is certain is how old the trust in them is along this coast.'],[('z','Do these rites really work?'),('b','That’s for the believer, Zappy. What’s certain is how many generations have trusted them.')],'A coast’s <b>old trust</b>.'),
 reading('shashthi','CAMPĀ ṢAṢṬHĪ AT KUKKE','The great chariot',svg(560,170,'A huge chariot pulled by crowds through the temple street below forested hills',f'<rect width="560" height="170" fill="#e3f5e9"/>'+hills(560,140)+g(300,150,1.8,chariot())+''.join(g(x,155,.5,person('#2a5aa8')) for x in range(110,260,18))),['<b>When.</b> Mārgaśīrṣa Śuddha Ṣaṣṭhī, the day of the wedding: Subrahmaṇya Ṣaṣṭhī, also called Campā Ṣaṣṭhī.','<b>The festival.</b> A run of days with processions, small chariots and lit nights, ending in the <b>Brahmaratha</b>, the great chariot, pulled by devotees through the car street.','<b>Other days.</b> <b>Kiru Ṣaṣṭhī</b>, the “small Ṣaṣṭhī”; '+L('/festivals/naga-panchami/','Nāgara Pañcamī')+'; Nāgārādhane.','<b>Feeding.</b> The busiest days of the year, and pilgrims are fed by the temple, true to the name Annadāta Subbappa.'],[('z','How many people pull it?'),('b','Thousands, Zappy. Everyone who can get a hand on the rope.')],'A whole town <b>pulls together</b>.'),
 reading('history','HISTORY','Priests, maṭhas and the State',svg(560,150,'A coastal temple with a sloping tiled roof',f'<rect width="560" height="150" fill="#e3f5e9"/>'+'<path d="M180 130 v-50 h200 v50z" fill="#c9a06a"/><path d="M160 80 l120 -50 l120 50z" fill="#8a3a2a"/>'+g(450,130,1.4,book())),['<b>Paraśurāma kṣetra.</b> Kukke is counted among the seven holy places of the coast said to be set up by Paraśurāma.','<b>Style.</b> The temple is built in the Karnataka coastal style: sloping tiled roofs, wood and granite.','<b>Stewards and priests.</b> The Koojugodu Kattemane family long served as chief administrators, with close ties to Śṛṅgeri; the priesthood changed hands between Brahmin communities in the nineteenth century, and the Śrī Subrahmaṇya Sabhā was founded in 1908.','<b>Today.</b> The temple is run by the Karnataka Endowment Department and is among the state’s best-known pilgrim centres.'],[('z','Why so many groups in one temple’s story?'),('b','Big temples gather many hands, Zappy. The god stays the same; the stewards change.')],'Many hands, <b>one shrine</b>.'),
 reading('around','AROUND KUKKE','The sacred landscape',svg(560,170,'A peak, a river and a sacred grove, with an eagle flying far away',f'<rect width="560" height="170" fill="#e3f5e9"/>'+g(200,160,1.8,mountain('#5a7a4a',False))+'<path d="M0 150 q280 -10 560 0 v20 h-560z" fill="#8fb8de"/>'+''.join(g(x,150,.7,tree('#2f6a3a')) for x in (400,440,480))+g(520,40,.5,bird('#c0582a'))),['<b>Kumāra Parvata.</b> The peak above Kukke, sacred as the place of the wedding; a well-known forest trek.','<b>Kumāradhārā.</b> The river of the wedding waters, where pilgrims bathe.','<b>Garuḍa folklore.</b> Locals say Garuḍa never flies over the temple or the peak, out of respect for Vāsuki’s refuge. (Folklore; we have not verified it.)','<b>Serpent country.</b> The coast of Tuḷunāḍu is full of nāga groves (<b>nāgabana</b>), honoured by every family. Next: '+L('/subramanya/ghati/','Ghāṭi Subrahmaṇya')+', the serpent shrine near Bengaluru.'],[('z','Eagles really avoid it?'),('b','So the locals say, Zappy. Watch the sky next time and tell me.')],'Forest, river <b>and serpent groves</b>.'),
 end(i,['<b>Where.</b> Kukke, on the Kumāradhārā in the forests of Dakṣiṇa Kannaḍa.','<b>Story.</b> Vāsuki hid from Garuḍa in Biladvāra; Subrahmaṇya promised to stay forever.','<b>Shrine.</b> Subrahmaṇya above, Vāsuki and Śeṣa below, a Garuḍa pillar; Ādi Subrahmaṇya’s anthill.','<b>Rites.</b> Sarpa saṃskāra, āśleṣā bali, nāga pratiṣṭhā.','<b>Day.</b> Campā Ṣaṣṭhī, the wedding day, with the Brahmaratha.'],'Part 4: '+L('/subramanya/ghati/','Ghāṭi Subrahmaṇya')+', with a secret: two gods in one stone.','Kukke Subrahmaṇya'),
 sources([('Temple and legend:','Wikipedia, “Kukke Subramanya Temple” and “Subramanya, Karnataka”; kukkedevasthanam.org.in (Skanda Purāṇa, Sahyādri Khaṇḍa; Campā Ṣaṣṭhī as the wedding); other sources as summarised in our earlier guide.'),('Verse:','Subrahmaṇya Bhujaṅgam, verse 5, as on shlokam.org.')],'the Garuḍa folklore; the order of the three tiers (as commonly described); the meaning of “Kukke”; details of the Vāsuki story and the wedding (traditions differ); entry and rite arrangements (set by the temple).','Interpretations are marked as such.')]
build(i,'PART 3 OF 4 · VĀSUKI’S REFUGE · THE GREAT CHARIOT',COV,'The serpent’s refuge in the forest','The <b>legends</b> of Vāsuki and the wedding, a walk through the <b>sanctum</b>, Ādi Subrahmaṇya and the Kukke liṅga, a verse of the Bhujaṅgam, the <b>nāga rites</b>, and Campā Ṣaṣṭhī’s <b>chariot</b>.','Kukke Subrahmaṇya explained: Vāsuki and Garuḍa, the wedding at Kumāra Parvata and the Kumāradhārā, the three-tiered sanctum and Garuḍa pillar, Ādi Subrahmaṇya’s anthill and Biladvāra, the Kukke liṅga and Śaṅkara, Subrahmaṇya Bhujaṅgam verse 5, the nāga rites, Campā Ṣaṣṭhī and the Brahmaratha, and the temple’s history. Part 3 of 4.',pp)
print('kukke',len(pp)+2)
# ---------- PART 4: GHĀṬI ----------
i=3
COV=covart('A seven-hooded cobra image facing one way and Narasiṃha the other, a mirror between, nāga stones and bullocks at a fair',f'<rect width="440" height="196" fill="#fde9c8"/>'+hills(440,170)+'<rect y="170" width="440" height="26" fill="#e9d6c0"/>'+g(160,170,1.4,cobra(hoods=7))+g(280,170,1.2,narasimha())+g(220,120,.9,mirror())+g(60,186,.8,nagakallu())+g(380,186,.9,bull()))
pp=[foreword(i,['An hour north of Bengaluru, in the dry hills of Doḍḍaballāpura, stands a temple with one of the strangest images in Karnataka. Facing east is <b>Subrahmaṇya</b>, as a seven-hooded cobra. Facing west, on the back, is <b>Lakṣmī Narasiṃha</b>. You see the cobra directly, and Narasiṃha in a mirror.','The story is the theme of '+L('/subramanya/kukke/','Kukke')+' told another way: the son of Śiva took the form of a serpent, and Viṣṇu himself, as Narasiṃha, guarded him from Garuḍa. This last part visits Ghāṭi: the name, the legends, the image and the mirror, the forest of nāga stones, the history, the chariot festival and its famous cattle fair a month after Subrahmaṇya Ṣaṣṭhī.'],[('z','Śiva’s son and Viṣṇu in one stone?'),('b','Back to back, protecting each other, Zappy. Ghāṭi settles every Śaiva–Vaiṣṇava quarrel without a word.')]),
 glance([('Where','Ghāṭi Subrahmaṇya, near Tūbagere, Doḍḍaballāpura taluk, about 60 km north of Bengaluru'),('God','Subrahmaṇya as a seven-hooded cobra, facing east'),('With him','Lakṣmī Narasiṃha, facing west, seen in a mirror'),('Image','Held to be svayambhū, self-manifested; tradition says one stone'),('History','More than 600 years by temple records; developed by the Ghorpaḍe rulers of Sandūr'),('Known for','Vows for children, thousands of nāga stones, worship for Ketu'),('Festival','Brahmarathotsava on Puṣya Śuddha Ṣaṣṭhī, with a famous cattle fair')],svg(560,140,'A cobra image and Narasiṃha back to back with a mirror',f'<rect width="560" height="140" fill="#fde9c8"/>'+g(230,130,1.2,cobra(hoods=7))+g(330,130,1,narasimha())+g(280,100,.8,mirror()))),
 reading('name','THE NAME','Pot, hill or demon?',svg(560,160,'A cobra hood shaped like a pot, a hill, and a fallen demon',f'<rect width="560" height="160" fill="#fde9c8"/>'+g(120,140,1.2,cobra(hoods=7))+g(120,60,.7,pot('#c98a5a'))+g(290,150,1.2,mountain('#9a8a6a',False))+g(450,150,1,demon('#5a3a6a'))),['<b>Ghaṭa sarpa.</b> A popular explanation: the cobra’s spread hood looks like a pot (<i>ghaṭa</i>); the god lived here as a “pot-hooded serpent”.','<b>Ghāṭ.</b> Another: “ghāṭ”, the hill country where the temple stands.','<b>Ghaṭikāsura.</b> A third: the demon Ghaṭikāsura, said to have been killed here.','<b>Full name.</b> Śrī Ghāṭi Subrahmaṇya Svāmi Kṣetra; tradition counts it among seven <i>svayaṃvyakta</i> (self-revealed) shrines of Subrahmaṇya.'],[('z','Which one is right?'),('b','Traditions differ, Zappy. All three tell you something about the place: a serpent, a hill and a victory.')],'A serpent, a hill, <b>a victory</b>.'),
 story('penance','THE SERPENT’S PENANCE','Why the god became a cobra',strip('Three panels: Skanda arriving in dry hills; meditating in the form of a seven-hooded cobra; the frightened serpents around him',[panel([(skanda(),.9),(mountain('#9a8a6a',False),.6)],'#fde9c8',150),panel([(cobra(hoods=7),1.1)],'#e9d6c0',150),panel([(cobra(),.6),(cobra('#4a6a8a'),.6),(garuda(),.5)],'#dfe9f6',150)],['to the hills','the cobra’s penance','the nāgas’ fear']),'Ghāṭi temple tradition; tellings differ.',['Tradition says Subrahmaṇya came to these hills and did penance in the form of a serpent.','Why? In one telling, it was before his war with Tāraka; in another, to atone after the killing in that war.','A local story adds a demon, <b>Ghaṭikāsura</b>, whom the god destroyed here.','While he lived here as a serpent, he learned that the nāgas around him lived in fear of <b>Garuḍa</b>.','He turned to Viṣṇu for help. That is the next page.'],[('z','The war-god did penance as a snake?'),('b','Even heroes need quiet, Zappy. The hills of Ghāṭi gave him that.')],'The warrior <b>becomes a serpent</b>.'),
 story('narasimha','NARASIṂHA GUARDS THE NĀGAS','Viṣṇu stands behind',strip('Three panels: the serpent-god asking Viṣṇu for help; Lakṣmī Narasiṃha arriving and holding back Garuḍa; the two forms standing back to back',[panel([(cobra(hoods=7),.9),(vishnu(),.8)],'#e3eaf3',150),panel([(narasimha(),1),(garuda(),.6)],'#fde9c8',150),panel([(cobra(hoods=7),.8),(narasimha(),.8)],'#fff3cf',150)],['the request','Garuḍa held back','back to back']),'Ghāṭi temple tradition.',['Subrahmaṇya asked Viṣṇu to keep his mount Garuḍa from harming the serpents.','Viṣṇu came with Lakṣmī as <b>Lakṣmī Narasiṃha</b> and stood guard over him.','Garuḍa could not touch the serpents here; Narasiṃha gave them <b>abhaya</b>, freedom from fear.','Sages (one telling names Mārkaṇḍeya) prayed that both forms stay here together. So the image shows the cobra facing east and Narasiṃha facing west.','The same theme as Kukke: there the son protects the serpent from Garuḍa; at Ghāṭi Viṣṇu himself holds his own eagle back.'],[('z','Viṣṇu stopped his own eagle?'),('b','For his nephew, Zappy. Family first.')],'Viṣṇu holds back <b>his own eagle</b>.'),
 reading('mirror','THE IMAGE AND THE MIRROR','How you see both gods',svg(560,170,'A devotee standing before a cobra image, a mirror on the side showing Narasiṃha on the image’s back',f'<rect width="560" height="170" fill="#fffaf0"/>'+g(240,160,1.4,cobra(hoods=7))+g(310,160,1.1,narasimha())+g(430,130,1.4,mirror())+g(120,160,1.1,namaste('#c0392b'))+'<path d="M330 100 l90 0" stroke="#e0a800" stroke-dasharray="4 4" stroke-width="2"/>'),['<b>East face.</b> Subrahmaṇya as a seven-hooded cobra: the main darśan.','<b>West face.</b> Lakṣmī Narasiṃha, on the back of the same image.','<b>The mirror.</b> A large mirror in the sanctum shows Narasiṃha to devotees standing before Subrahmaṇya, so both are seen at once without walking round.','<b>Svayambhū.</b> Both are held to have risen from the earth, not carved by hands. Most say one stone; some descriptions speak of two images back to back.'],[('z','Why a mirror?'),('b','Because the two gods face opposite ways, Zappy. The mirror lets you see both at once.')],'Two gods, <b>one glance</b>.'),
 reading('stones','THE FOREST OF NĀGA STONES','Vows for children',svg(560,170,'Rows of carved serpent stones under trees with a couple praying',f'<rect width="560" height="170" fill="#cfe0d8"/>'+'<rect y="140" width="560" height="30" fill="#a8c890"/>'+''.join(g(x,150,.7,nagakallu()) for x in range(60,360,40))+g(420,150,1,person('#c0392b'))+g(470,150,1,person('#2a5aa8'))+g(260,150,1.2,tree('#2f6a3a'))),['<b>Nāga stones.</b> Thousands of stone serpent images stand near the temple, set up by devotees over generations.','<b>Harake.</b> A vow (<i>harake</i> in Kannaḍa): couples pray here for children and return to fulfil it, very often by installing a nāga stone (<b>nāga pratiṣṭhā</b>).','<b>Ketu.</b> The temple is also a centre of worship for Ketu, the shadow planet linked with serpents.','<b>Sarpa doṣa.</b> As at Kukke, devotees come for relief from troubles believed to follow harm to snakes.'],[('z','Every stone is a vow?'),('b','Every one, Zappy. And many are a child’s story.')],'A forest <b>of answered prayers</b>.'),
 verse('v-nava','Nava Nāga Stotra','The nine great serpents',['anantaṃ vāsukiṃ śeṣaṃ padmanābhaṃ ca kambalam','śaṅkhapālaṃ dhārtarāṣṭraṃ takṣakaṃ kāliyaṃ tathā','etāni nava nāmāni nāgānāṃ ca mahātmanām','sāyaṅkāle paṭhen nityaṃ prātaḥkāle viśeṣataḥ','tasya viṣabhayaṃ nāsti sarvatra vijayī bhavet'],svg(200,150,'Nine small cobras in a semicircle',f'<rect width="200" height="150" fill="#cfe0d8"/>'+''.join(g(100+80*math.cos(3.14+k*0.39),130+60*math.sin(3.14+k*0.39),.45,cobra()) for k in range(9))),'Ananta, Vāsuki, Śeṣa, Padmanābha and Kambala, Śaṅkhapāla, Dhārtarāṣṭra, Takṣaka and Kāliya: these are the nine names of the great serpents. Whoever recites them every evening, and especially in the morning, has no fear of poison and is victorious everywhere.',[('anantam','Ananta, the endless'),('vāsukim','Vāsuki'),('śeṣam','Śeṣa'),('takṣakam','Takṣaka'),('viṣa-bhayam','fear of poison'),('vijayī','victorious')],'<b>The serpents’ roll-call.</b> At a shrine where the god himself is a seven-hooded cobra and thousands of nāga stones stand, this verse of the nine great serpents is recited by many pilgrims. Vāsuki of '+L('/subramanya/kukke/','Kukke')+' and Śeṣa of Viṣṇu’s couch are both in it.',k='Nine names <b>against fear</b>.',note='Text as on shlokam.org and sanskritdocuments.org (Navanāganāmastotram), as on our '+L('/festivals/naga-panchami/','Nāga Pañcamī')+' page.'),
 reading('history','HISTORY','The Ghorpaḍes of Sandūr',svg(560,150,'A Dravidian-style temple with a gopura in dry hills',f'<rect width="560" height="150" fill="#fde9c8"/>'+hills(560,140)+g(280,130,1.1,palace())),['<b>Recorded history.</b> More than six hundred years, by temple records.','<b>The Ghorpaḍes.</b> The temple was first developed by the Ghorpaḍes, rulers of the small state of <b>Sandūr</b>, who governed parts of Baḷḷāri, over 300 km away: kings built for gods wherever their faith took them.','<b>Style and priests.</b> A Dravidian-style temple with a gopura; tradition says one family has served as priests for generations.','<b>Today.</b> A major pilgrim centre of the Bengaluru Rural region, busiest on Sundays, Ṣaṣṭhīs and the chariot festival.'],[('z','Sandūr is far from Bengaluru, isn’t it?'),('b','Over 300 km, Zappy. Devotion travels.')],'Kings who built <b>far from home</b>.'),
 reading('fair','THE CHARIOT AND THE CATTLE FAIR','Puṣya Ṣaṣṭhī at Ghāṭi',svg(560,170,'A chariot with crowds and, in the field beside, rows of decorated bullocks at a fair',f'<rect width="560" height="170" fill="#fde9c8"/>'+'<rect y="140" width="560" height="30" fill="#e9d6c0"/>'+g(140,150,1.6,chariot())+''.join(g(x,155,.8,bull()) for x in (320,390,460,530))),['<b>Brahmarathotsava.</b> The great chariot festival falls on <b>Puṣya Śuddha Ṣaṣṭhī</b>, one lunar month after '+L('/subramanya/shashthi/','Subrahmaṇya Ṣaṣṭhī')+', and the image is drawn round the temple by devotees.','<b>The cattle fair.</b> Around the festival is held one of the best-known cattle fairs of South India, with farmers from Karnataka, Tamil Nadu, Andhra Pradesh and beyond buying and selling bullocks under the god’s blessing.','<b>Other days.</b> Subrahmaṇya Ṣaṣṭhī itself is kept with special worship; <b>Narasiṃha Jayantī</b> is the other great festival, for the god on the west face; Kārtika Pūrṇimā draws crowds too.','<b>The old way.</b> In rural Karnataka the god’s festival was always also the farmers’ market: the jātre brings together faith, trade and family.'],[('z','A cattle fair at a temple?'),('b','The old way, Zappy. The god’s festival was the farmers’ market; bullocks were bought under his blessing.')],'Faith and <b>the farmers’ market</b>.'),
 cards('compare','KUKKE AND GHĀṬI','Two serpent shrines side by side',fig_row('A forest temple and a hill temple, each with a serpent',[(palace(),.6),(cobra(hoods=7),1),(palace(),.6),(narasimha(),1)],['Kukke','Vāsuki','Ghāṭi','Narasiṃha'],gy=150),[('🌳','Setting','Kukke: rainforest of the west coast. Ghāṭi: dry hills near Bengaluru.'),('🐍','Form','Kukke: Subrahmaṇya above Vāsuki and Śeṣa. Ghāṭi: Subrahmaṇya himself as a seven-hooded cobra.'),('🛡️','Protector','Kukke: Subrahmaṇya protects Vāsuki from Garuḍa. Ghāṭi: Narasiṃha protects the nāgas.'),('🚩','Chariot','Kukke: Mārgaśīrṣa Ṣaṣṭhī. Ghāṭi: Puṣya Ṣaṣṭhī, a month later. Shared: nāga vows, sarpa doṣa, and the god of Karnataka’s serpents.')],[('z','Which should I visit?'),('b','Both, Zappy, a month apart. Start the series again with '+L('/subramanya/skanda/','Who is Skanda?')+'.')],'One god, <b>two shrines</b>.'),
 end(i,['<b>Where.</b> Ghāṭi, near Doḍḍaballāpura, about 60 km from Bengaluru.','<b>Image.</b> A seven-hooded cobra facing east; Lakṣmī Narasiṃha facing west, seen in a mirror.','<b>Story.</b> The god’s penance as a serpent; Narasiṃha guards the nāgas from Garuḍa.','<b>Vows.</b> Thousands of nāga stones; prayers for children; Ketu.','<b>Festival.</b> Puṣya Ṣaṣṭhī chariot and the great cattle fair.'],'That completes the series. Begin again with '+L('/subramanya/skanda/','Part 1: Who is Skanda?')+'.','Ghāṭi Subrahmaṇya'),
 sources([('Temple and legend:','Wikipedia, “Ghati Subramanya” and temple and press sources (image and mirror, Ghorpaḍes of Sandūr, nāga stones, Brahmarathotsava, cattle fair), as summarised in our earlier guide.'),('Verse:','Nava Nāga Stotra from shlokam.org and sanskritdocuments.org.')],'the origin of the name (traditions differ); the reasons for the serpent penance (tellings differ); whether the image is one stone or two; the 600-year history (temple records); fair dates and arrangements (vary yearly).','Interpretations are marked as such.')]
build(i,'PART 4 OF 4 · TWO GODS IN ONE STONE · THE CATTLE FAIR',COV,'Cobra, Narasiṃha and the mirror','The <b>name</b>, the god’s <b>penance as a serpent</b> and Narasiṃha’s guard, the image and the <b>mirror</b>, the forest of nāga stones, the history, and the chariot and <b>cattle fair</b>.','Ghāṭi Subrahmaṇya explained: the name, the serpent penance, Lakṣmī Narasiṃha guarding the nāgas from Garuḍa, the seven-hooded cobra and the mirror, the forest of nāga stones and vows for children, the Nava Nāga Stotra, the Ghorpaḍes of Sandūr, the Puṣya Ṣaṣṭhī chariot and cattle fair, and Kukke compared. Part 4 of 4.',pp)
print('ghati',len(pp)+2)
